preConditionHook:
// BROOKS'S CONSECUTIVE CLIMAXES, stated entirely in bar anatomy: THIS bar is a
// large bull trend bar, and a SECOND large bull trend bar printed between 2 and
// maxGapBars bars ago with at least one bar between them that was NOT a bull
// trend bar. Short is the mirror.
//
// NOT COMPOSABLE: "two large trend bars with a pause between them" is a pattern
// over a VARIABLE offset, not an AND of per-bar tests.
//
// NOT ConsecutiveClimaxBarCount, which is the LEVEL reading of the same idea:
// it counts separated climaxes anywhere in a 30-bar window and stays true for
// bars afterwards, and it never requires the CURRENT bar to be a climax. This
// rule is the EVENT -- it fires on the second climax bar itself and only while
// the pair is within maxGapBars. Same distinction the corpus draws between
// HighLowBarCount and LegCountAtLeast.
//
// THE PAUSE test is weaker than the count rule's: the separating bar need only
// fail to be a with-trend TREND bar, not fail to be a CLIMAX. That is what
// Brooks means by a pause -- the market stopped going, not merely stopped going
// violently.
//
// ii starts at 2, so there is always at least one bar between the two climaxes
// and the inner scan is never empty.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. Same block as AtrProfitTarget and ConsecutiveClimaxBarCount,
// including the TWO separate accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently. One ATR read serves every bar of the scan,
// which keeps the rule off the ATR variable's own zero-filled history.
//
// Products, not quotients: EasyLanguage raises a runtime divide-by-zero and a
// zero-range bar is legal data.
//
// Deepest bar touched: max(maxGapBars, atrLookback + 1).
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLookback;
bigUpNow = el_gt(close[0], open[0]) && el_ge(close[0] - open[0], bodyFraction * (high[0] - low[0])) && el_ge(high[0] - low[0], sizeMultiple * atrValue);
bigDnNow = el_lt(close[0], open[0]) && el_ge(open[0] - close[0], bodyFraction * (high[0] - low[0])) && el_ge(high[0] - low[0], sizeMultiple * atrValue);
foundUp = false;
foundDn = false;
for (ii = 2; ii <= (int)maxGapBars; ++ii) {
    bigUpK = el_gt(close[ii], open[ii])
        && el_ge(close[ii] - open[ii], bodyFraction * (high[ii] - low[ii]))
        && el_ge(high[ii] - low[ii], sizeMultiple * atrValue);
    bigDnK = el_lt(close[ii], open[ii])
        && el_ge(open[ii] - close[ii], bodyFraction * (high[ii] - low[ii]))
        && el_ge(high[ii] - low[ii], sizeMultiple * atrValue);
    pauseUp = false;
    pauseDn = false;
    for (jj = 1; jj <= ii - 1; ++jj) {
        trendUpJ = el_gt(close[jj], open[jj])
            && el_ge(close[jj] - open[jj], bodyFraction * (high[jj] - low[jj]));
        trendDnJ = el_lt(close[jj], open[jj])
            && el_ge(open[jj] - close[jj], bodyFraction * (high[jj] - low[jj]));
        if (trendUpJ == false) pauseUp = true;
        if (trendDnJ == false) pauseDn = true;
    }
    if (bigUpK && pauseUp) foundUp = true;
    if (bigDnK && pauseDn) foundDn = true;
}
